package com.fasterxml.jackson.core.util;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.io.SerializedString;
import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for DefaultPrettyPrinter.createInstance()
 */
public class DefaultPrettyPrinter_createInstance_TriageGen1Test {

    @Test
    public void testCreateInstance_Standard() {
        // Arrange
        DefaultPrettyPrinter original = new DefaultPrettyPrinter();

        // Act
        DefaultPrettyPrinter instance = original.createInstance();

        // Assert
        assertNotNull("The created instance should not be null", instance);
        assertNotSame("The created instance should be a new object, not the same reference", original, instance);
    }

    @Test
    public void testCreateInstance_WithCustomConfiguration() {
        // Arrange
        DefaultPrettyPrinter original = new DefaultPrettyPrinter();
        original.indentArraysWith(new DefaultPrettyPrinter.Indenter() {
            @Override
            public void writeIndentation(com.fasterxml.jackson.core.util.JsonGenerator g, int len) throws java.io.IOException {
                // dummy
            }
        });
        original.withSpacesInObjectEntries();

        // Act
        DefaultPrettyPrinter instance = original.createInstance();

        // Assert
        assertNotNull(instance);
        // Since the constructor DefaultPrettyPrinter(DefaultPrettyPrinter base) is used,
        // we verify that the instance is a different object but logically derived.
        // Note: We cannot easily check internal private state without reflection, 
        // but we verify the creation process completes successfully.
        assertNotSame(original, instance);
    }

    @Test
    public void testCreateInstance_WithRootSeparator() {
        // Arrange
        DefaultPrettyPrinter original = new DefaultPrettyPrinter("{\n");

        // Act
        DefaultPrettyPrinter instance = original.createInstance();

        // Assert
        assertNotNull(instance);
        assertNotSame(original, instance);
    }

    @Test
    public void testCreateInstance_WithComplexSettings() {
        // Arrange
        DefaultPrettyPrinter original = new DefaultPrettyPrinter();
        original.withArrayIndenter(new DefaultPrettyPrinter.Indenter() {
            @Override
            public void writeIndentation(com.fasterxml.jackson.core.util.JsonGenerator g, int len) throws java.io.IOException {}
        });
        original.withObjectIndenter(new DefaultPrettyPrinter.Indenter() {
            @Override
            public void writeIndentation(com.fasterxml.jackson.core.util.JsonGenerator g, int len) throws java.io.IOException {}
        });

        // Act
        DefaultPrettyPrinter instance = original.createInstance();

        // Assert
        assertNotNull(instance);
        assertNotSame(original, instance);
    }
}
